-- ============================================================================
-- marketing ROI by channel — governed report query
-- ----------------------------------------------------------------------------
-- Generated by: analyst (governed agent run run-6fa20d91c8e3)
-- Plan (allowed through the gateway):
--   query marketing.campaign_attribution -> allow (allow-read-sensitive)
-- ============================================================================

select
    channel,
    sum(spend)                      as total_spend,
    sum(revenue_attributed)         as attributed_revenue,
    round(sum(revenue_attributed) / nullif(sum(spend), 0), 2) as roi,
    count(distinct campaign_id)     as campaigns
from `marketing.campaign_attribution`
where attribution_date >= date_add(@run_date, interval -90 day)
group by channel
order by roi desc
